def _norm(value):
    text = str(value or "").strip().lower().replace("đ", "d")
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    return re.sub(r"[^a-z0-9]+", " ", text).strip()

def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def _normalized_text_hash(path: Path) -> str:
    text = path.read_text(encoding="utf-8")
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

def _file_state(root: Path, rel: str) -> str:
    path = root / rel
    if not path.exists():
        return "missing"
    raw = _sha256_bytes(path.read_bytes())
    if raw == PATCHED_HASHES[rel]:
        return "patched"
    if raw == EXPECTED_RAW_HASHES[rel]:
        return "original"
    try:
        if _normalized_text_hash(path) == EXPECTED_NORMALIZED_HASHES[rel]:
            return "original"
    except Exception:
        pass
    return "unknown"

def _backup_sqlite(db_path: Path, backup_path: Path) -> None:
    src = sqlite3.connect(str(db_path))
    try:
        dst = sqlite3.connect(str(backup_path))
        try:
            src.backup(dst)
            dst.commit()
            check = dst.execute("PRAGMA integrity_check").fetchone()[0]
            fk = dst.execute("PRAGMA foreign_key_check").fetchall()
            if str(check).lower() != "ok" or fk:
                raise RuntimeError(f"Backup database không đạt kiểm tra: integrity={check}, FK={len(fk)}")
        finally:
            dst.close()
    finally:
        src.close()

def _school(con: sqlite3.Connection, code: str):
    row = con.execute(
        "SELECT s.id,s.code,s.name,s.commune_id,s.is_active,c.name commune_name "
        "FROM schools s LEFT JOIN communes c ON c.id=s.commune_id WHERE s.code=?",
        (code,),
    ).fetchone()
    if row is None:
        raise RuntimeError(f"Không tìm thấy trường mã {code}.")
    return row

def _year_id(con: sqlite3.Connection, code: str) -> int:
    row = con.execute("SELECT id FROM school_years WHERE code=?", (code,)).fetchone()
    if row is None:
        raise RuntimeError(f"Không tìm thấy năm học {code}.")
    return int(row["id"])

def _resolve_source_members(con: sqlite3.Connection):
    resolved = []
    for item in SOURCE_STAFF:
        member = con.execute(
            "SELECT id,ministry_staff_code,full_name,date_of_birth FROM staff_members WHERE ministry_staff_code=?",
            (item["code"],),
        ).fetchone()
        if member is None:
            raise RuntimeError(
                f"Không tìm thấy staff_member mã {item['code']} - {item['name']}; dừng để tránh sửa nhầm."
            )
        if _norm(member["full_name"]) != _norm(item["name"]):
            raise RuntimeError(
                f"Mã {item['code']} hiện thuộc '{member['full_name']}', không khớp '{item['name']}'; dừng."
            )
        resolved.append({**item, "staff_member_id": int(member["id"])})
    return resolved

def _ids_sql(ids):
    return ",".join("?" for _ in ids) if ids else "NULL"

def _count_staff_ids(con, ids, year_id, school_id):
    if not ids:
        return 0
    return int(con.execute(
        f"SELECT COUNT(*) FROM staff_year_records WHERE staff_member_id IN ({_ids_sql(ids)}) "
        "AND school_year_id=? AND school_id=?",
        [*ids, year_id, school_id],
    ).fetchone()[0] or 0)

def _count_users(con, usernames, school_id):
    if not usernames:
        return 0
    return int(con.execute(
        f"SELECT COUNT(*) FROM users WHERE username IN ({_ids_sql(usernames)}) AND school_id=?",
        [*usernames, school_id],
    ).fetchone()[0] or 0)

def _snapshot(con):
    source = _school(con, SOURCE_SCHOOL_CODE)
    target = _school(con, TARGET_SCHOOL_CODE)
    wrong_hist = _school(con, WRONG_HISTORY_SCHOOL_CODE)
    wrong_current = _school(con, WRONG_CURRENT_SCHOOL_CODE)
    past_id = _year_id(con, PAST_YEAR_CODE)
    current_id = _year_id(con, CURRENT_YEAR_CODE)
    members = _resolve_source_members(con)
    all_ids = [x["staff_member_id"] for x in members]
    active = [x for x in members if x["status"] in ACTIVE_SOURCE_LABELS]
    active_ids = [x["staff_member_id"] for x in active]
    teacher_usernames = [f"gv.{x['code']}" for x in active if x["position"] == "Giáo viên"]

    return {
        "source": dict(source),
        "target": dict(target),
        "wrong_hist": dict(wrong_hist),
        "wrong_current": dict(wrong_current),
        "past_year_id": past_id,
        "current_year_id": current_id,
        "members": members,
        "all_ids": all_ids,
        "active_ids": active_ids,
        "teacher_usernames": teacher_usernames,
        "source_hist_matches": _count_staff_ids(con, all_ids, past_id, int(source["id"])),
        "wrong_hist_matches": _count_staff_ids(con, all_ids, past_id, int(wrong_hist["id"])),
        "target_current_matches": _count_staff_ids(con, active_ids, current_id, int(target["id"])),
        "wrong_current_matches": _count_staff_ids(con, active_ids, current_id, int(wrong_current["id"])),
        "target_current_total": int(con.execute(
            "SELECT COUNT(*) FROM staff_year_records WHERE school_id=? AND school_year_id=?",
            (int(target["id"]), current_id),
        ).fetchone()[0] or 0),
        "wrong_current_total": int(con.execute(
            "SELECT COUNT(*) FROM staff_year_records WHERE school_id=? AND school_year_id=?",
            (int(wrong_current["id"]), current_id),
        ).fetchone()[0] or 0),
        "source_teacher_users_at_target": _count_users(con, teacher_usernames, int(target["id"])),
        "source_teacher_users_at_wrong": _count_users(con, teacher_usernames, int(wrong_current["id"])),
    }

def _classify_state(snap):
    pre = (
        snap["source_hist_matches"] == 0
        and snap["wrong_hist_matches"] == 41
        and snap["target_current_matches"] == 0
        and snap["wrong_current_matches"] == 34
        and snap["target_current_total"] == 48
        and snap["source_teacher_users_at_target"] == 0
        and snap["source_teacher_users_at_wrong"] == 23
    )
    post = (
        snap["source_hist_matches"] == 41
        and snap["wrong_hist_matches"] == 0
        and snap["target_current_matches"] == 34
        and snap["wrong_current_matches"] == 0
        and snap["target_current_total"] == 82
        and snap["source_teacher_users_at_target"] == 23
        and snap["source_teacher_users_at_wrong"] == 0
    )
    return "pre" if pre else ("post" if post else "unknown")

def _verify_merger_log(con, snap):
    if not con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='school_merger_operations'").fetchone():
        raise RuntimeError("Thiếu bảng school_merger_operations; không xác nhận được lần sáp nhập V4.1.")
    rows = con.execute(
        "SELECT id,school_year_id,target_school_id,source_school_ids_json,created_at "
        "FROM school_merger_operations WHERE school_year_id=? AND target_school_id=? ORDER BY id DESC",
        (snap["current_year_id"], snap["target"]["id"]),
    ).fetchall()
    source_id = int(snap["source"]["id"])
    for row in rows:
        try:
            ids = [int(x) for x in json.loads(row["source_school_ids_json"] or "[]")]
        except Exception:
            continue
        if source_id in ids:
            return dict(row)
    raise RuntimeError("Không tìm thấy nhật ký sáp nhập Nghi Hoà -> Nghi Hải năm 2026-2027.")

def _write_patched_files(root: Path, backup_dir: Path):
    states = {}
    for rel in PATCHED_FILES_B64:
        state = _file_state(root, rel)
        states[rel] = state
        if state == "unknown" or state == "missing":
            raise RuntimeError(
                f"Tệp {rel} không đúng phiên bản nguồn mong đợi (state={state}). "
                "Dừng để không ghi đè thay đổi khác."
            )

    # Backup mã nguồn trước khi thay.
    for rel, state in states.items():
        src = root / rel
        dst = backup_dir / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)

    # Ghi tệp mới vào .tmp, compile Python, rồi replace atomically.
    temp_paths = []
    try:
        for rel, b64 in PATCHED_FILES_B64.items():
            path = root / rel
            if states[rel] == "patched":
                continue
            data = base64.b64decode(b64)
            tmp = path.with_suffix(path.suffix + ".v42.tmp")
            tmp.write_bytes(data)
            temp_paths.append(tmp)
            if path.suffix == ".py":
                py_compile.compile(str(tmp), doraise=True)
            if _sha256_bytes(data) != PATCHED_HASHES[rel]:
                raise RuntimeError(f"Payload V4.2 của {rel} sai hash nội bộ.")
        for rel in PATCHED_FILES_B64:
            path = root / rel
            if states[rel] == "patched":
                continue
            tmp = path.with_suffix(path.suffix + ".v42.tmp")
            os.replace(tmp, path)
    finally:
        for tmp in temp_paths:
            if tmp.exists():
                try:
                    tmp.unlink()
                except Exception:
                    pass
    return states

def _restore_source_files(root: Path, backup_dir: Path):
    for rel in PATCHED_FILES_B64:
        src = backup_dir / rel
        dst = root / rel
        if src.exists():
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

def _repair_database(db_path: Path, backup_db_path: Path):
    con = sqlite3.connect(str(db_path))
    con.row_factory = sqlite3.Row
    try:
        con.execute("PRAGMA foreign_keys=ON")
        before = _snapshot(con)
        op = _verify_merger_log(con, before)
        state = _classify_state(before)
        if state == "post":
            return before, before, op, "already_repaired"
        if state != "pre":
            raise RuntimeError(
                "Trạng thái database không đúng mẫu an toàn V4.2. "
                f"source_hist={before['source_hist_matches']}, wrong_hist={before['wrong_hist_matches']}, "
                f"target_current={before['target_current_matches']}, wrong_current={before['wrong_current_matches']}, "
                f"target_total={before['target_current_total']}, users_target={before['source_teacher_users_at_target']}, "
                f"users_wrong={before['source_teacher_users_at_wrong']}. "
                "Không sửa tự động; cần gửi ZIP mã nguồn/database hiện tại để đối chiếu."
            )

        if int(before["source"]["is_active"] or 0) != 0:
            raise RuntimeError("Trường Nghi Hoà chưa inactive như kết quả V4.1; dừng.")
        # Tài khoản trường nguồn phải đã khóa.
        source_login = con.execute(
            "SELECT id,username,is_active FROM users WHERE school_id=? AND username LIKE 'truong_%' ORDER BY id LIMIT 1",
            (before["source"]["id"],),
        ).fetchone()
        if source_login is None or int(source_login["is_active"] or 0) != 0:
            raise RuntimeError("Tài khoản trường Nghi Hoà chưa ở trạng thái khóa; dừng.")

        con.execute("BEGIN IMMEDIATE")
        # 41 hồ sơ lịch sử 2025-2026 bị gán nhầm sang Nghi Hoa (Nghi Lộc).
        hist_ids = []
        for item in before["members"]:
            row = con.execute(
                "SELECT school_id FROM staff_year_records WHERE staff_member_id=? AND school_year_id=?",
                (item["staff_member_id"], before["past_year_id"]),
            ).fetchone()
            if row is not None and int(row["school_id"]) == int(before["wrong_hist"]["id"]):
                hist_ids.append(item["staff_member_id"])
        if len(hist_ids) != 41:
            raise RuntimeError(f"Số hồ sơ lịch sử cần trả về Nghi Hoà không còn là 41 mà là {len(hist_ids)}.")
        cur = con.execute(
            f"UPDATE staff_year_records SET school_id=? "
            f"WHERE staff_member_id IN ({_ids_sql(hist_ids)}) AND school_year_id=? AND school_id=?",
            [before["source"]["id"], *hist_ids, before["past_year_id"], before["wrong_hist"]["id"]],
        )
        if cur.rowcount != 41:
            raise RuntimeError(f"Chuyển lịch sử chỉ cập nhật {cur.rowcount}/41 dòng.")

        # 34 hồ sơ CURRENT 2026-2027 đã rollover nhầm sang Nghi Trung.
        current_ids = before["active_ids"]
        cur = con.execute(
            f"UPDATE staff_year_records SET school_id=? "
            f"WHERE staff_member_id IN ({_ids_sql(current_ids)}) AND school_year_id=? AND school_id=?",
            [before["target"]["id"], *current_ids, before["current_year_id"], before["wrong_current"]["id"]],
        )
        if cur.rowcount != 34:
            raise RuntimeError(f"Chuyển đội ngũ CURRENT chỉ cập nhật {cur.rowcount}/34 dòng.")

        # 23 tài khoản GV tương ứng cũng đang gán nhầm Nghi Trung.
        usernames = before["teacher_usernames"]
        cur = con.execute(
            f"UPDATE users SET school_id=? WHERE username IN ({_ids_sql(usernames)}) AND school_id=?",
            [before["target"]["id"], *usernames, before["wrong_current"]["id"]],
        )
        if cur.rowcount != 23:
            raise RuntimeError(f"Chuyển tài khoản giáo viên chỉ cập nhật {cur.rowcount}/23 tài khoản.")

        con.execute(
            "CREATE TABLE IF NOT EXISTS school_merger_staff_repair_logs ("
            "id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "version TEXT NOT NULL,"
            "source_school_id INTEGER NOT NULL,"
            "target_school_id INTEGER NOT NULL,"
            "school_year_id INTEGER NOT NULL,"
            "history_rows_repaired INTEGER NOT NULL,"
            "current_rows_repaired INTEGER NOT NULL,"
            "teacher_accounts_repaired INTEGER NOT NULL,"
            "backup_name TEXT,"
            "details_json TEXT NOT NULL,"
            "created_at TEXT NOT NULL"
            ")"
        )
        details = {
            "merger_operation_id": op["id"],
            "wrong_history_school": before["wrong_hist"],
            "wrong_current_school": before["wrong_current"],
            "known_conflicts": KNOWN_CONFLICTS,
        }
        con.execute(
            "INSERT INTO school_merger_staff_repair_logs("
            "version,source_school_id,target_school_id,school_year_id,"
            "history_rows_repaired,current_rows_repaired,teacher_accounts_repaired,"
            "backup_name,details_json,created_at"
            ") VALUES (?,?,?,?,?,?,?,?,?,?)",
            (
                VERSION,
                before["source"]["id"],
                before["target"]["id"],
                before["current_year_id"],
                41,34,23,
                backup_db_path.name,
                json.dumps(details, ensure_ascii=False),
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            ),
        )

        integrity = str(con.execute("PRAGMA integrity_check").fetchone()[0])
        fk = con.execute("PRAGMA foreign_key_check").fetchall()
        if integrity.lower() != "ok" or fk:
            raise RuntimeError(f"Hậu kiểm trước COMMIT thất bại: integrity={integrity}, FK={len(fk)}")

        after = _snapshot(con)
        if _classify_state(after) != "post":
            raise RuntimeError(
                "Hậu kiểm số liệu V4.2 chưa đạt mẫu POST; rollback toàn bộ."
            )
        con.commit()
        return before, after, op, "repaired"
    except Exception:
        try:
            con.rollback()
        except Exception:
            pass
        raise
    finally:
        con.close()

def _write_report(root: Path, before, after, op, mode, backup_db_path, backup_dir):
    out_dir = root / "exports" / "Bai_Sap_Nhap_V4_2_Sua_Doi_Ngu_Cua_Lo"
    out_dir.mkdir(parents=True, exist_ok=True)
    report = out_dir / f"bao_cao_V4_2_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
    lines = [
        "BÀI SÁP NHẬP V4.2 - BÁO CÁO SỬA ĐỘI NGŨ CỬA LÒ",
        "=" * 78,
        f"Chế độ: {mode}",
        f"Nhật ký sáp nhập tham chiếu: {op.get('id')}",
        f"Backup DB: {backup_db_path.name}",
        f"Backup mã nguồn: {backup_dir}",
        "",
        "TRƯỚC:",
        f"- Hồ sơ Nghi Hoà 2025-2026 đúng trường: {before['source_hist_matches']}",
        f"- Hồ sơ Cửa Lò bị gán nhầm Nghi Hoa/Nghi Lộc: {before['wrong_hist_matches']}",
        f"- Hồ sơ nguồn đang ở Nghi Hải 2026-2027: {before['target_current_matches']}",
        f"- Hồ sơ nguồn bị rollover nhầm Nghi Trung: {before['wrong_current_matches']}",
        f"- Tổng đội ngũ Nghi Hải 2026-2027: {before['target_current_total']}",
        f"- Tài khoản GV nguồn đang ở Nghi Hải: {before['source_teacher_users_at_target']}",
        f"- Tài khoản GV nguồn đang nhầm Nghi Trung: {before['source_teacher_users_at_wrong']}",
        "",
        "SAU:",
        f"- Hồ sơ Nghi Hoà 2025-2026 đúng trường: {after['source_hist_matches']}",
        f"- Hồ sơ còn nhầm Nghi Hoa/Nghi Lộc: {after['wrong_hist_matches']}",
        f"- Hồ sơ nguồn đã về Nghi Hải 2026-2027: {after['target_current_matches']}",
        f"- Hồ sơ nguồn còn ở Nghi Trung: {after['wrong_current_matches']}",
        f"- Tổng đội ngũ Nghi Hải 2026-2027: {after['target_current_total']}",
        f"- Tài khoản GV nguồn đã về Nghi Hải: {after['source_teacher_users_at_target']}",
        f"- Tài khoản GV nguồn còn ở Nghi Trung: {after['source_teacher_users_at_wrong']}",
        "",
        "KẾT QUẢ CANONICAL AN TOÀN SAU V4.2:",
        "- Nghi Hải 2026-2027: 82 hồ sơ đội ngũ = 58 giáo viên + 21 nhân viên + 3 CBQL.",
        "- Trong đó V4.2 bổ sung đúng 34 hồ sơ từ Nghi Hoà và chuyển 23 tài khoản giáo viên.",
        "- Nghi Hoà 2025-2026 tra cứu lại được 41 hồ sơ nguồn đã bị gán nhầm.",
        "",
        "3 XUNG ĐỘT FILE NGUỒN KHÔNG TỰ SỬA:",
    ]
    for i, issue in enumerate(KNOWN_CONFLICTS, 1):
        lines += [
            f"{i}. Mã {issue['code']}: {issue['issue']}",
            f"   - {issue['row_a']}",
            f"   - {issue['row_b']}",
            f"   - Xử lý: {issue['action']}",
        ]
    lines += [
        "",
        "LƯU Ý:",
        "- File nguồn cho thấy tổng hoạt động thô của Nghi Hải + Nghi Hoà là 84 người.",
        "- Database hiện chỉ có thể khẳng định an toàn 82 người vì 2 dòng hoạt động còn mâu thuẫn:",
        "  Nguyễn Thị Minh Trang (mã trùng 4002902252) và Trần Thị Ngọc (đang ở 2 trường cùng năm).",
        "- Không tiếp tục các phương án sáp nhập khác trước khi kiểm tra màn hình Đội ngũ và tài khoản sau V4.2.",
    ]
    report.write_text("\n".join(lines), encoding="utf-8")
    return report

def main():
    root = Path(__file__).resolve().parent
    db_path = root / "data" / "phocap.db"
    if not (root / "app").is_dir() or not db_path.exists():
        raise RuntimeError("Hãy chép bộ cài vào đúng thư mục gốc C:\\PhoCap rồi chạy tại đó.")

    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / f"backup_bai_sap_nhap_v4_2_{ts}"
    backup_dir.mkdir(parents=True, exist_ok=False)
    backup_db_dir = root / "backups"
    backup_db_dir.mkdir(parents=True, exist_ok=True)
    backup_db_path = backup_db_dir / f"backup_truoc_sua_doi_ngu_v4_2_{ts}.db"

    # 1. Kiểm tra mã nguồn trước.
    for rel in PATCHED_FILES_B64:
        state = _file_state(root, rel)
        print(f"[SOURCE] {rel}: {state}")
        if state not in {"original", "patched"}:
            raise RuntimeError(f"Tệp {rel} khác phiên bản dự kiến. Không cài V4.2.")

    # 2. Kiểm tra database và xác định trạng thái trước khi backup.
    pre_con = sqlite3.connect(str(db_path))
    pre_con.row_factory = sqlite3.Row
    try:
        snap0 = _snapshot(pre_con)
        op0 = _verify_merger_log(pre_con, snap0)
        state0 = _classify_state(snap0)
    finally:
        pre_con.close()
    print("[DB] Trạng thái:", state0)
    if state0 not in {"pre", "post"}:
        raise RuntimeError("Database không ở trạng thái PRE/POST an toàn của V4.2; dừng.")

    # 3. Backup DB + mã nguồn.
    _backup_sqlite(db_path, backup_db_path)
    print("[BACKUP DB]", backup_db_path)
    source_states = _write_patched_files(root, backup_dir)
    print("[BACKUP SOURCE]", backup_dir)

    try:
        before, after, op, mode = _repair_database(db_path, backup_db_path)
        report = _write_report(root, before, after, op, mode, backup_db_path, backup_dir)
    except Exception:
        # Khôi phục mã nguồn nếu sửa DB thất bại.
        _restore_source_files(root, backup_dir)
        raise

    print()
    print("=" * 78)
    print("BÀI SÁP NHẬP V4.2 - CÀI ĐẶT THÀNH CÔNG")
    print("=" * 78)
    print("Chế độ:", mode)
    print("Nghi Hoà 2025-2026: 41 hồ sơ lịch sử đã có thể tra cứu.")
    print("Nghi Hải 2026-2027: 82 hồ sơ đội ngũ canonical an toàn.")
    print("Tài khoản GV từ Nghi Hoà chuyển đúng về Nghi Hải: 23.")
    print("Đã sửa import: khóa theo Xã/phường + Tên trường khi không có Mã trường.")
    print("Đã mở tra cứu trường inactive ở Đội ngũ năm lịch sử và tìm tài khoản khóa.")
    print("Còn 3 xung đột nguồn được giữ nguyên để xác minh; xem báo cáo:")
    print(report)
    print()
    print("KHÔNG chạy phương án sáp nhập tiếp theo trước khi kiểm tra Nghi Hải/Nghi Hoà.")

if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print()
        print("V4.2 KHÔNG THỰC HIỆN / ĐÃ DỪNG AN TOÀN:")
        print(str(exc))
        sys.exit(1)
